// Paid replay of a code-review reconciler, operator-chosen 2026-10-13
// ("Option 2", cap $0.10): Haiku 5.5, medium effort, BuildWorks' executor
// flags unchanged, cwd the clone at bb7f3f6. Input: run 6's 13 round-1
// findings exactly as stored, the approved spec and plan, the reviewed diff.
// Labels (fixed before any call): reject 200; keep 195 197 198 199 201 202
// 203 204 205; either 196 206 207.
import { readFileSync, writeFileSync, appendFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { spawnSync } from "node:child_process";
const BW = "file:///C:/Users/Shawn-work/repositories/governed-delivery/";
const { invokeHarness, parseEnvelope } = await import(BW + "src/harness.ts");
const { CLAUDE_CODE } = await import(BW + "src/executor.ts");
const { extractJsonBody } = await import(BW + "src/parse-output.ts");

const DIR = process.argv[2];
const N = Number(process.argv[3] ?? "10");
const CAP = 0.1;
const CWD = join(DIR, "cc6");
const OUT = join(DIR, "out-reconciler");
const LOG = join(OUT, "results.jsonl");
const T = "C:/Users/Shawn-work/repositories/testing-repos/crew-chatter";
const spec = readFileSync(join(T, "docs/features/crew-chatter-foundation/spec.md"), "utf8");
const plan = readFileSync(join(T, "docs/features/crew-chatter-foundation/plan.md"), "utf8");
const BASE = "01f9a11180c6b6f24e7f00d828e4b348e31e36ba", HEAD = "bb7f3f673a3b4d452d07782c54f13881f281fbd5";
const diff = spawnSync("git", ["diff", "--no-color", BASE, HEAD], { cwd: T, encoding: "utf8", maxBuffer: 64 << 20 }).stdout;
const fx = JSON.parse(readFileSync("C:/Users/Shawn-work/repositories/governed-delivery/test/fixtures/recorded/code-review-crew-chatter-run-6.json", "utf8"));
const findings = fx.codeReviewFindings.filter((f) => f.round === 1);
if (findings.length !== 13) throw new Error(`expected 13 round-1 findings, got ${findings.length}`);

const rendered = findings
  .map((f) => `- finding ${f.findingId}; location ${f.location}; intentKey ${f.intentKey}\n${f.reports.map((r) => `  - reviewer ${r.reviewer}; severity ${r.severity}; subject ${r.subject}`).join("\n")}`)
  .join("\n");
const ids = findings.map((f) => f.findingId);

const prompt = `you are the code-review reconciler

Code reviewers reported the findings below against a committed change. Decide, for each finding, whether the implementer must fix it before the next review. Your working directory is the repository checkout at commit ${HEAD}; you may read it. Run no git commands and do not create, modify, or delete any file.

Keep a finding when the code fails a behavior the approved specification or plan states, or breaks in ordinary use: it crashes, loses or corrupts data, returns a wrong result, or lets a user read or change data the specification does not allow.
Reject a finding only when it asks for protection, limits, or policy beyond what the approved specification states, and the specification already states a workable baseline for that behavior. A rejection must quote that baseline: words copied exactly from the approved specification, which the system checks.
When you are unsure, keep the finding: a kept finding costs one fix, and a wrongly rejected one ships a defect.

Return exactly one JSON object, with no surrounding prose and no markdown fences:
{"decisions": [${ids.map((id) => `{"findingId": ${id}, <the remaining fields of one shape below>}`).join(", ")}]}

The decisions list has exactly one entry per finding id listed below, no more and no fewer. Each decision takes exactly one of these shapes:
- keep: {"findingId": <id>, "disposition": "keep", "basis": "<basis>"} where basis is exactly one of: an acceptance criterion ID copied from the approved specification (for example AC-001); the text "plan task: " followed by the first five words of that task, copied exactly from the approved plan (for example "plan task: Create the notes API in"); or one of crash, data-loss, wrong-result, unauthorized-access.
- reject: {"findingId": <id>, "disposition": "reject", "rationale": "<one sentence>", "excerpt": "<the specification's exact words stating the baseline>"}

Findings:

${rendered}

Approved specification:

${spec}

Approved plan:

${plan}

Diff of the change:

${diff}`;

const collapse = (s) => s.replace(/\s+/g, " ").trim();
const specFlat = collapse(spec);
const planFlat = collapse(plan);
const acIds = new Set([...spec.matchAll(/^- (AC-\d{3,}):/gm)].map((m) => m[1]));
function check(decisions) {
  const problems = [];
  if (!Array.isArray(decisions)) return ["decisions is not an array"];
  const seen = decisions.map((d) => d.findingId);
  for (const id of ids) if (seen.filter((x) => x === id).length !== 1) problems.push(`finding ${id} has ${seen.filter((x) => x === id).length} decisions`);
  for (const d of decisions) {
    if (!ids.includes(d.findingId)) problems.push(`unknown finding ${d.findingId}`);
    if (d.disposition === "reject") {
      if (typeof d.excerpt !== "string" || d.excerpt.trim() === "" || !specFlat.includes(collapse(d.excerpt))) problems.push(`finding ${d.findingId} reject excerpt not in spec`);
    } else if (d.disposition === "keep") {
      const b = String(d.basis ?? "");
      const taskWords = /^plan task: (.+)$/.exec(b)?.[1];
      const ok = (/^AC-\d{3,}$/.test(b) && acIds.has(b)) || (taskWords !== undefined && planFlat.includes(collapse(taskWords))) || ["crash", "data-loss", "wrong-result", "unauthorized-access"].includes(b);
      if (!ok) problems.push(`finding ${d.findingId} keep basis invalid: ${b}`);
    } else problems.push(`finding ${d.findingId} disposition ${d.disposition}`);
  }
  return problems;
}

let spent = 0;
if (existsSync(LOG)) for (const l of readFileSync(LOG, "utf8").split("\n").filter(Boolean)) spent += JSON.parse(l).cost ?? 0;
writeFileSync(join(OUT, "prompt.txt"), prompt);
for (let i = 1; i <= N; i++) {
  if (existsSync(join(OUT, `rec-${i}.raw.jsonl`))) continue;
  if (spent >= CAP) { console.log(`stop before rec-${i}: spent ${spent.toFixed(4)} >= ${CAP}`); break; }
  const outcome = await invokeHarness(CLAUDE_CODE, { prompt, model: "claude-haiku-5-5", effort: "medium", cwd: CWD });
  writeFileSync(join(OUT, `rec-${i}.raw.jsonl`), outcome.raw);
  let env = null; try { env = parseEnvelope(CLAUDE_CODE, outcome.raw); } catch {}
  const cost = env?.cost ?? 0; spent += cost;
  let decisions = null, parseError = null;
  if (env) { const b = extractJsonBody(env.resultText); if (b.kind === "ok") decisions = b.value?.decisions ?? null; else parseError = b.reason; }
  const problems = decisions ? check(decisions) : [parseError ?? "no envelope"];
  appendFileSync(LOG, JSON.stringify({ label: `rec-${i}`, cost, exitCode: outcome.exitCode, durationMs: outcome.durationMs, problems, decisions }) + "\n");
  const rejected = (decisions ?? []).filter((d) => d.disposition === "reject").map((d) => d.findingId);
  console.log(`rec-${i}: cost ${cost.toFixed(4)} rejected [${rejected.join(",")}] problems ${problems.length} total ${spent.toFixed(4)}`);
}
console.log(`done; total ${spent.toFixed(4)}`);
